SELECT CASE WHEN institution_type ILIKE '%Hospital%' THEN 'H' ELSE 'L' END AS seg, DATE_TRUNC('month', invoice_date)::date AS mes, SUM(presented_value) AS apresentado FROM curated.totvs_procedure_invoice WHERE system_source = 'totvs-alice' AND provider_class = 'Health Institution' AND invoice_step IN ('1-Digitacao','2-Conferencia','3-Pronta','4-Faturada') AND (institution_type ILIKE '%Clinica%' OR institution_type ILIKE '%Laboratorio%' OR institution_type ILIKE '%Hospital%') AND invoice_date >= '2026-03-01' AND invoice_date <= '2026-11-17' GROUP BY 1,2
